  <script>
    'use strict';

    /* ── Estado ── */
    const state = {
      cantidadFirmantes: 1,
      vistaTab: true,
      tabActiva: 0,
      pasoActual: 1,
    };

    /* ── Referencia a elementos ── */
    const cantidadInput      = document.getElementById('cantidad-firmantes');
    const btnMenos           = document.getElementById('btn-menos');
    const btnMas             = document.getElementById('btn-mas');
    const firmantesContainer = document.getElementById('firmantes-container');
    const btnEnviar          = document.getElementById('btn-enviar');
    const modalOverlay       = document.getElementById('modal-overlay');
    const btnModalCerrar     = document.getElementById('btn-modal-cerrar');
    const modalBody          = document.getElementById('modal-body');
    const btnVistaLista      = document.getElementById('btn-vista-lista');
    const btnVistaTabs       = document.getElementById('btn-vista-tabs');
    const btnAnterior        = document.getElementById('btn-anterior');
    const btnSiguiente       = document.getElementById('btn-siguiente');

    /* ── Función para generar el HTML interno de un firmante ── */
    function signerFormHTML(i) {
      const num = i + 1;
      return `
        <div class="signer-grid">
          <div class="form-group">
            <label for="nombre-${i}">Nombre <span class="required-star">*</span></label>
            <input type="text" id="nombre-${i}" placeholder="Ej: Juan" autocomplete="given-name" />
            <span class="field-error" id="error-nombre-${i}">Ingresá el nombre.</span>
          </div>
          <div class="form-group">
            <label for="apellido-${i}">Apellido <span class="required-star">*</span></label>
            <input type="text" id="apellido-${i}" placeholder="Ej: Pérez" autocomplete="family-name" />
            <span class="field-error" id="error-apellido-${i}">Ingresá el apellido.</span>
          </div>
          <div class="form-group">
            <label for="dni-${i}">DNI <span class="required-star">*</span></label>
            <input type="text" id="dni-${i}" placeholder="Ej: 28456789" maxlength="8" inputmode="numeric" />
            <span class="field-error" id="error-dni-${i}">Ingresá un DNI válido (7-8 dígitos).</span>
          </div>
          <div class="form-group">
            <label for="email-${i}">Email <span class="required-star">*</span></label>
            <input type="email" id="email-${i}" placeholder="juan@email.com" autocomplete="email" />
            <span class="field-error" id="error-email-${i}">Ingresá un email válido.</span>
          </div>
        </div>
      `;
    }

    /* ── Adjuntar listeners a los inputs de un firmante ── */
    function attachSignerListeners(container, i) {
      const nombreInput   = container.querySelector(`#nombre-${i}`);
      const apellidoInput = container.querySelector(`#apellido-${i}`);
      const preview       = container.querySelector(`#preview-nombre-${i}`);
      const dniInput      = container.querySelector(`#dni-${i}`);

      if (preview) {
        const actualizarPreview = () => {
          const n = nombreInput.value.trim();
          const a = apellidoInput.value.trim();
          preview.textContent = (n || a) ? `${n} ${a}`.trim() : '';
        };
        nombreInput.addEventListener('input', actualizarPreview);
        apellidoInput.addEventListener('input', actualizarPreview);
      } else {
        /* En vista tabs el preview está en la tab, no en el panel */
        const actualizarTab = () => {
          const n = nombreInput.value.trim();
          const a = apellidoInput.value.trim();
          const tabBtn = document.getElementById(`tab-btn-${i}`);
          if (tabBtn) {
            const label = (n || a) ? `${n} ${a}`.trim() : `Firmante ${i + 1}`;
            tabBtn.dataset.label = label;
            const span = tabBtn.querySelector('span');
            if (span) span.textContent = label;
          }
        };
        nombreInput.addEventListener('input', actualizarTab);
        apellidoInput.addEventListener('input', actualizarTab);
      }

      dniInput.addEventListener('input', () => {
        dniInput.value = dniInput.value.replace(/\D/g, '');
      });
    }

    /* ── Generar formularios de firmantes ── */
    function renderFirmantes() {
      firmantesContainer.innerHTML = '';

      if (state.vistaTab) {
        /* ── VISTA TABS ── */
        const tabsBar = document.createElement('div');
        tabsBar.className = 'tabs-bar';
        tabsBar.id = 'tabs-bar';

        for (let i = 0; i < state.cantidadFirmantes; i++) {
          const btn = document.createElement('button');
          btn.type = 'button';
          btn.className = 'tab-btn' + (i === state.tabActiva ? ' active' : '');
          btn.id = `tab-btn-${i}`;
          btn.dataset.label = `Firmante ${i + 1}`;
          btn.innerHTML = `<span>${'Firmante ' + (i + 1)}</span>`;
          btn.addEventListener('click', () => {
            state.tabActiva = i;
            document.querySelectorAll('.tab-btn').forEach((b, idx) => {
              b.classList.toggle('active', idx === i);
            });
            document.querySelectorAll('.tab-panel').forEach((p, idx) => {
              p.classList.toggle('active', idx === i);
            });
          });
          tabsBar.appendChild(btn);
        }
        firmantesContainer.appendChild(tabsBar);

        for (let i = 0; i < state.cantidadFirmantes; i++) {
          const panel = document.createElement('div');
          panel.className = 'tab-panel signer-card' + (i === state.tabActiva ? ' active' : '');
          panel.id = `tab-panel-${i}`;
          panel.innerHTML = signerFormHTML(i);
          firmantesContainer.appendChild(panel);
          attachSignerListeners(panel, i);
        }

      } else {
        /* ── VISTA LISTA ── */
        for (let i = 0; i < state.cantidadFirmantes; i++) {
          const num = i + 1;
          const div = document.createElement('div');
          div.className = 'signer-card';
          div.dataset.index = i;
          div.innerHTML = `
            <div class="signer-header">
              <span class="signer-badge">Firmante ${num}</span>
              <span class="signer-name-preview" id="preview-nombre-${i}"></span>
            </div>
            ${signerFormHTML(i)}
          `;
          firmantesContainer.appendChild(div);
          attachSignerListeners(div, i);
        }
      }

    }

    /* ── Actualizar indicador de pasos ── */
    function actualizarSteps() {
      for (let s = 1; s <= 3; s++) {
        const el = document.getElementById(`step-${s}`);
        if (s < state.pasoActual)        el.className = 'step done';
        else if (s === state.pasoActual) el.className = 'step active';
        else                             el.className = 'step';
      }
    }

    /* ── Mostrar paso del wizard ── */
    function mostrarPaso(n) {
      state.pasoActual = n;
      for (let s = 1; s <= 3; s++) {
        document.getElementById(`panel-paso-${s}`).classList.toggle('active', s === n);
      }
      actualizarSteps();
      btnAnterior.classList.toggle('hidden', n === 1);
      if (n === 3) {
        btnSiguiente.style.display = 'none';
        btnEnviar.style.display    = '';
      } else {
        btnSiguiente.style.display = '';
        btnEnviar.style.display    = 'none';
      }
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    /* ── Controles +/- ── */
    btnMenos.addEventListener('click', () => {
      if (state.cantidadFirmantes > 1) {
        state.cantidadFirmantes--;
        cantidadInput.value = state.cantidadFirmantes;
        renderFirmantes();
      }
    });

    btnMas.addEventListener('click', () => {
      if (state.cantidadFirmantes < 10) {
        state.cantidadFirmantes++;
        cantidadInput.value = state.cantidadFirmantes;
        renderFirmantes();
      }
    });

    /* Cambio directo en input (teclado) */
    cantidadInput.addEventListener('change', () => {
      let val = parseInt(cantidadInput.value, 10);
      if (isNaN(val) || val < 1) val = 1;
      if (val > 10) val = 10;
      state.cantidadFirmantes = val;
      cantidadInput.value = val;
      renderFirmantes();
    });

    /* ── Toggle vista lista / tabs ── */
    btnVistaLista.addEventListener('click', () => {
      if (!state.vistaTab) return;
      state.vistaTab = false;
      state.tabActiva = 0;
      btnVistaLista.classList.add('active');
      btnVistaTabs.classList.remove('active');
      renderFirmantes();
    });

    btnVistaTabs.addEventListener('click', () => {
      if (state.vistaTab) return;
      state.vistaTab = true;
      state.tabActiva = 0;
      btnVistaTabs.classList.add('active');
      btnVistaLista.classList.remove('active');
      renderFirmantes();
    });

    /* ── Navegación del wizard ── */
    btnAnterior.addEventListener('click', () => {
      mostrarPaso(state.pasoActual - 1);
    });

    btnSiguiente.addEventListener('click', () => {
      if (state.pasoActual === 1) {
        if (!validarPaso1()) {
          const firstError = document.querySelector('.file-input-wrap.error, select.error, input.error');
          if (firstError) firstError.scrollIntoView({ behavior: 'smooth', block: 'center' });
          return;
        }
        mostrarPaso(2);
      } else if (state.pasoActual === 2) {
        if (!validarPaso2()) {
          if (state.vistaTab) {
            const firstErrTab = document.querySelector('.tab-btn.has-error');
            if (firstErrTab) {
              const idx = parseInt(firstErrTab.id.replace('tab-btn-', ''), 10);
              state.tabActiva = idx;
              document.querySelectorAll('.tab-btn').forEach((b, i) => b.classList.toggle('active', i === idx));
              document.querySelectorAll('.tab-panel').forEach((p, i) => p.classList.toggle('active', i === idx));
              firstErrTab.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
          } else {
            const firstError = document.querySelector('input.error');
            if (firstError) firstError.scrollIntoView({ behavior: 'smooth', block: 'center' });
          }
          return;
        }
        renderResumen();
        mostrarPaso(3);
      }
    });

    /* ── Step indicator: ir atrás ── */
    document.getElementById('step-1').addEventListener('click', () => {
      if (state.pasoActual > 1) mostrarPaso(1);
    });
    document.getElementById('step-2').addEventListener('click', () => {
      if (state.pasoActual > 2) mostrarPaso(2);
    });

    /* ── Validación ── */
    function setFieldError(id, errorId, show) {
      const input = document.getElementById(id);
      const error = document.getElementById(errorId);
      if (!input || !error) return;
      if (show) {
        input.classList.add('error');
        error.classList.add('visible');
      } else {
        input.classList.remove('error');
        error.classList.remove('visible');
      }
    }

    function validarPaso1() {
      let valido = true;

      const tipoDoc = document.getElementById('tipo-documento');
      const tipoDocInvalido = !tipoDoc.value;
      setFieldError('tipo-documento', 'error-tipo-documento', tipoDocInvalido);
      if (tipoDocInvalido) valido = false;

      const nroOp = document.getElementById('nro-operacion');
      const nroOpInvalido = !nroOp.value.trim();
      setFieldError('nro-operacion', 'error-nro-operacion', nroOpInvalido);
      if (nroOpInvalido) valido = false;

      const docInput = document.getElementById('documento');
      const sinDoc = docInput.files.length === 0;
      setFileError(sinDoc);
      if (sinDoc) valido = false;

      return valido;
    }

    function validarPaso2() {
      let valido = true;

      for (let i = 0; i < state.cantidadFirmantes; i++) {
        const nombre   = document.getElementById(`nombre-${i}`);
        const apellido = document.getElementById(`apellido-${i}`);
        const dni      = document.getElementById(`dni-${i}`);
        const email    = document.getElementById(`email-${i}`);

        const nombreInvalido   = !nombre.value.trim();
        const apellidoInvalido = !apellido.value.trim();
        const dniInvalido      = !/^\d{7,8}$/.test(dni.value.trim());
        const emailInvalido    = !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim());

        setFieldError(`nombre-${i}`,   `error-nombre-${i}`,   nombreInvalido);
        setFieldError(`apellido-${i}`, `error-apellido-${i}`, apellidoInvalido);
        setFieldError(`dni-${i}`,      `error-dni-${i}`,      dniInvalido);
        setFieldError(`email-${i}`,    `error-email-${i}`,    emailInvalido);

        const firmanteTieneError = nombreInvalido || apellidoInvalido || dniInvalido || emailInvalido;
        if (firmanteTieneError) valido = false;

        if (state.vistaTab) {
          const tabBtn = document.getElementById(`tab-btn-${i}`);
          if (tabBtn) tabBtn.classList.toggle('has-error', firmanteTieneError);
        }
      }

      return valido;
    }

    /* ── File input personalizado ── */
    const fileWrap   = document.getElementById('file-wrap');
    const fileBtn    = document.getElementById('file-btn');
    const fileInput  = document.getElementById('documento');
    const fileNameEl = document.getElementById('file-name');

    function triggerFileInput() { fileInput.click(); }

    fileWrap.addEventListener('click', triggerFileInput);
    fileWrap.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); triggerFileInput(); }
    });

    fileInput.addEventListener('change', () => {
      const file = fileInput.files[0];
      if (file) {
        fileNameEl.textContent = file.name;
        fileNameEl.classList.add('selected');
      } else {
        fileNameEl.textContent = 'Ningún archivo seleccionado';
        fileNameEl.classList.remove('selected');
      }
      /* Quitar error */
      fileWrap.classList.remove('error');
      document.getElementById('error-documento').classList.remove('visible');
    });

    /* Adaptar validación para usar fileWrap en vez de input */
    function setFileError(show) {
      if (show) {
        fileWrap.classList.add('error');
        document.getElementById('error-documento').classList.add('visible');
      } else {
        fileWrap.classList.remove('error');
        document.getElementById('error-documento').classList.remove('visible');
      }
    }

    /* ── Envío ── */
    btnEnviar.addEventListener('click', async () => {
      const docFile       = document.getElementById('documento').files[0];
      const tipoDocumento = document.getElementById('tipo-documento').value;
      const nroOperacion  = document.getElementById('nro-operacion').value.trim();
      const firmantes = [];

      for (let i = 0; i < state.cantidadFirmantes; i++) {
        firmantes.push({
          nombre:   document.getElementById(`nombre-${i}`).value.trim(),
          apellido: document.getElementById(`apellido-${i}`).value.trim(),
          dni:      document.getElementById(`dni-${i}`).value.trim(),
          email:    document.getElementById(`email-${i}`).value.trim(),
        });
      }

      /* UI: loading */
      btnEnviar.disabled = true;
      btnAnterior.disabled = true;
      btnEnviar.innerHTML = `<span class="spinner"></span> Enviando...`;

      try {
        await enviarSignZen(firmantes, docFile, tipoDocumento, nroOperacion);

        modalBody.innerHTML = `
          El documento <strong>"${sanitize(docFile.name)}"</strong> fue enviado correctamente.<br/>
          Los <strong>${firmantes.length}</strong> firmante${firmantes.length > 1 ? 's' : ''}
          recibirán una notificación por <strong>email</strong> con las instrucciones para completar la firma.
        `;
        abrirModal();

      } catch (err) {
        alert(`Error al enviar el documento: ${err.message}\n\nVerificá la conexión y volvé a intentarlo.`);
      } finally {
        btnEnviar.disabled = false;
        btnAnterior.disabled = false;
        btnEnviar.innerHTML = `
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2 .01 7z" fill="currentColor"/>
          </svg>
          Enviar para firmar`;
      }
    });

    /* ── Modal ── */
    function abrirModal() {
      modalOverlay.classList.add('open');
      btnModalCerrar.focus();
    }

    function limpiarFormulario() {
      /* Resetear tipo de documento y nro. de operación */
      document.getElementById('tipo-documento').value = '';
      document.getElementById('nro-operacion').value = '';

      /* Resetear cantidad de firmantes y tab activa */
      state.cantidadFirmantes = 1;
      state.tabActiva = 0;
      cantidadInput.value = 1;
      renderFirmantes();

      /* Resetear archivo */
      fileInput.value = '';
      fileNameEl.textContent = 'Ningún archivo seleccionado';
      fileNameEl.classList.remove('selected');
      fileWrap.classList.remove('error');
      /* Volver al paso 1 */
      mostrarPaso(1);
    }

    function cerrarModal() {
      modalOverlay.classList.remove('open');
      limpiarFormulario();
    }

    btnModalCerrar.addEventListener('click', cerrarModal);

    /* Cerrar con Escape o click fuera del modal */
    modalOverlay.addEventListener('click', (e) => {
      if (e.target === modalOverlay) cerrarModal();
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && modalOverlay.classList.contains('open')) cerrarModal();
    });

    /* ── Sanitización básica para XSS (sólo para mostrar en HTML) ── */
    function sanitize(str) {
      const div = document.createElement('div');
      div.appendChild(document.createTextNode(str));
      return div.innerHTML;
    }

    /* ── Resumen (paso 3) ── */
    function renderResumen() {
      const resumen    = document.getElementById('resumen-container');
      const tipoDoc    = document.getElementById('tipo-documento').value;
      const nroOp      = document.getElementById('nro-operacion').value.trim();
      const archivoNom = document.getElementById('file-name').textContent;

      let html = `
        <div class="summary-section">
          <div class="summary-section-title">Documento</div>
          <div class="summary-row">
            <span class="summary-label">Tipo</span>
            <span class="summary-value">${sanitize(tipoDoc)}</span>
          </div>
          <div class="summary-row">
            <span class="summary-label">Operación / Ref.</span>
            <span class="summary-value">${sanitize(nroOp)}</span>
          </div>
          <div class="summary-row">
            <span class="summary-label">Archivo</span>
            <span class="summary-value">${sanitize(archivoNom)}</span>
          </div>
        </div>
        <div class="summary-section">
          <div class="summary-section-title">Firmantes (${state.cantidadFirmantes})</div>
      `;

      for (let i = 0; i < state.cantidadFirmantes; i++) {
        const nombre   = document.getElementById(`nombre-${i}`).value.trim();
        const apellido = document.getElementById(`apellido-${i}`).value.trim();
        const dni      = document.getElementById(`dni-${i}`).value.trim();
        const email    = document.getElementById(`email-${i}`).value.trim();
        html += `
          <div class="summary-firmante">
            <div class="summary-firmante-title">Firmante ${i + 1}</div>
            <div class="summary-row">
              <span class="summary-label">Nombre completo</span>
              <span class="summary-value">${sanitize(nombre)} ${sanitize(apellido)}</span>
            </div>
            <div class="summary-row">
              <span class="summary-label">DNI</span>
              <span class="summary-value">${sanitize(dni)}</span>
            </div>
            <div class="summary-row">
              <span class="summary-label">Email</span>
              <span class="summary-value">${sanitize(email)}</span>
            </div>
          </div>
        `;
      }

      html += `</div>`;
      resumen.innerHTML = html;
    }

    /* ── Init ── */
    renderFirmantes();
  </script>
</body>
</html>
".replace('<!-- __GROUP_ID__ -->', injected);
return [{ json: { html } }];
